v(5,'미혹을 경계하라는 당부','예수께서 제자들에게 먼저 속임을 경계하라고 말씀하시고, 제자들은 주의 깊게 들어요.',['예수','제자들'],'look speak lift listen nod wait');
v(6,'자신을 그리스도라 내세우는 사람들','자신이 그리스도라고 주장하는 이들이 나타나 사람들을 흔들려는 장면을 경고의 표지로 보여요.',['거짓 그리스도','사람들','제자들'],'approach speak point turn retreat wait',{mode:'illustration',diagram:{kind:'warning',labels:['거짓 주장','흔들리는 사람들','분별하고 경계함']}});
v(7,'전쟁 소문 앞에서 두려워하지 말라','전쟁 소식이 들려와도 제자들이 공포에 휩쓸리지 않도록 예수께서 아직 끝은 아니라고 일러 주세요.',['예수','제자들','민족들'],'listen startle speak lower listen stand',{mode:'illustration',diagram:{kind:'warning',labels:['전쟁의 소문','두려움에 휩쓸리지 않음','끝은 아직 아님']}});
v(8,'분쟁과 지진과 기근의 시작','민족 간 분쟁, 흔들리는 땅, 메마른 밭을 세 칸 상징 장면으로 이어 보여요. 이를 마지막이 아니라 진통의 시작이라고 설명하세요.',['민족들','사람들','예수'],'turn brace lower look speak listen',{mode:'illustration',diagram:{kind:'comparison',labels:['민족의 대립','지진과 기근','재난의 시작']}});
v(9,'공회와 회당과 권력자 앞에 섬','제자들이 공회에 넘겨지고 회당에서 매를 맞으며, 예수 때문에 권력자들 앞에서 증언하게 될 일을 말씀하세요. 폭행은 직접 재현하지 않고 증언대 앞의 굳센 자세로 다뤄요.',['예수','제자들','사람들'],'look speak gather stand listen speak',{setting:'synagogue',emotion:'solemn'});
v(10,'모든 민족에게 먼저 전해질 복음','복음의 소식이 여러 민족에게 전해지는 흐름을 지도 위의 빛과 전달자들로 표현해요.',['제자들','민족들'],'gather speak turn walk extend show',{mode:'illustration',diagram:{kind:'map',labels:['복음의 시작','여러 민족에게 전함','증언의 확장']}});
v(11,'그때 주어질 말을 믿고 의지함','붙잡혀 심문받는 순간을 상징적으로 보여주며, 제자들이 미리 답을 걱정하지 말고 주어질 말을 하도록 격려하세요. 성령은 인물 형상 대신 빛으로 표현해요.',['예수','제자들','성령'],'walk halt listen speak look extend',{setting:'court',effect:'spirit-light'});
v(12,'가족 사이의 배신을 경고함','가까운 가족 사이에도 배신과 적대가 생길 수 있음을 경고하세요. 구체적인 살해 장면은 생략하고 서로 등지는 실루엣으로 표현해요.',['예수','사람들'],'turn retreat lower look speak listen',{mode:'illustration',diagram:{kind:'broken-tie',labels:['가족의 갈등','배신의 위협','폭력을 재현하지 않음']}});
v(13,'끝까지 견디는 사람의 소망','미움과 박해 속에서도 제자들이 서로를 붙들며 끝까지 견디라는 말씀을 들어요.',['예수','제자들','사람들'],'retreat brace reach stand speak listen',{emotion:'solemn'});
v(14,'산으로 피하라는 긴급한 경고','황폐하게 하는 표징을 보았을 때 유대에 있는 이들이 지체하지 말고 산으로 피하라는 긴급한 경고예요. 표징은 침략의 공포를 자극하지 않는 상징물로 표시해요.',['예수','사람들'],'look point startle turn run run',{setting:'mountain',effect:'flight'});
v(15,'지붕에서 집 안으로 되돌아가지 않음','지붕 위에 있는 이는 소지품을 챙기러 내려가지 말라는 말을 듣고 즉시 피난길을 택해요.',['사람들'],'look turn run run lower stand',{setting:'house'});
v(16,'밭에서 겉옷을 가지러 돌아서지 않음','밭에서 일하던 사람은 겉옷을 가지러 되돌아가지 않고 피하라는 경고를 받아요.',['사람들'],'look inspect turn run run stand');
v(17,'취약한 이들이 겪을 어려움을 헤아림','임신한 여인들과 젖먹이는 아이를 돌보는 이들이 피난의 어려움을 겪을 것을 예수께서 안타깝게 말씀하세요. 위협적인 장면이나 신체적 고통은 묘사하지 않아요.',['예수','임신한 여인들','아이에게 젖을 먹이는 여인들'],'look lower reach cover listen mourn',{emotion:'sad'});
v(18,'겨울을 피해 달라고 기도함','피난이 겨울에 닥치지 않도록 기도하라는 권면을 조용히 올리는 기도로 표현해요.',['예수','제자들'],'look kneel pray pray listen stand',{mode:'illustration',diagram:{kind:'comparison',labels:['피난의 어려움','겨울을 피하도록','기도하는 마음']}});
v(19,'전례없이 큰 환난을 알리심','예수께서 큰 환난의 무게를 말씀하세요. 인물의 고통을 재현하기보다 어두워지는 하늘과 비어 있는 길로 엄중함을 전달해요.',['예수','제자들'],'look speak lower listen retreat wait',{mode:'illustration',diagram:{kind:'warning',labels:['큰 환난','전례없는 어려움','엄중한 경고']}});
v(20,'택하신 이들을 위해 날을 감하심','환난의 날들이 감해져 선택된 이들이 보전된다는 말씀을, 짧아지는 달력과 다시 밝아지는 빛으로 상징해요.',['예수','제자들'],'look speak count lower listen bless',{mode:'illustration',diagram:{kind:'promise',labels:['감해진 날들','택하신 이들','보전하시는 은혜']}});
v(21,'여기 있다 저기 있다 해도 믿지 말라','그리스도가 여기 있다고 유인하는 말이 들려도 제자들이 따라가지 말라고 예수께서 다시 경계하세요.',['예수','제자들','사람들'],'look speak point retreat listen wait',{mode:'illustration',diagram:{kind:'warning',labels:['여기 있다는 주장','저기 있다는 주장','따라가지 말고 분별함']}});
v(22,'표적을 내세우는 거짓 지도자들','거짓 그리스도와 거짓 예언자가 표적을 앞세워 사람들을 미혹하려는 상황을 경고해요. 초자연 현상을 진짜 성취처럼 재현하지 않아요.',['거짓 그리스도','거짓 선지자','사람들','제자들'],'approach show speak turn retreat wait',{mode:'illustration',diagram:{kind:'warning',labels:['거짓 지도자','표적을 내세움','미혹을 경계함']}});
v(23,'미리 들은 말씀을 기억하라','예수께서 앞서 모든 일을 알려 주셨다고 상기시키며 제자들에게 깨어 분별하라고 하세요.',['예수','제자들'],'look speak point listen nod stand');
d(24,'환난 뒤 어두워지는 해와 달','환난 뒤 해가 어두워지고 달의 빛이 사라지는 우주적 표징을 어두운 하늘의 상징 장면으로 나타내요.','cosmic-dark',['환난 뒤의 표징','어두워진 해','빛을 잃은 달']);
d(25,'흔들리고 떨어지는 하늘의 별들','별과 하늘의 권세가 흔들리는 종말의 표상을 상징적 별빛과 진동하는 하늘로 보여요.','sky-sign',['흔들리는 하늘','떨어지는 별빛','권능의 동요']);
d(26,'구름 가운데 오는 인자','인자가 큰 권능과 영광으로 오는 장면은 인물을 과장해 신격화하지 않고, 구름과 빛을 통해 사람들이 바라보는 상징 연출로 구성해요.','glory-cloud',['구름 가운데 오심','큰 권능','영광을 바라보는 사람들']);
v(27,'사방에서 모이는 선택된 사람들','천사들이 사방에서 선택된 사람들을 모으는 장면을 흩어진 점들이 한곳으로 모이는 지도 연출로 나타내요.',['천사들','사람들'],'gather walk extend gather look stand',{mode:'illustration',diagram:{kind:'gather-call',labels:['땅 끝에서','하늘 끝까지','사방에서 모임']}});
v(28,'잎이 돋는 무화과나무의 계절','무화과나무의 가지가 부드러워지고 새잎이 나오는 변화를 살펴 여름이 가까움을 아는 비유예요.',['제자들'],'look touch show wait smile stand',{prop:'tree',setting:'garden',effect:'leaf-growth'});
v(29,'표징을 보고 가까움을 알아차림','예수께서 앞서 말한 일들이 보이면 인자가 가까이 왔음을 알아차리라고 비유를 적용하세요.',['예수','제자들'],'look point speak listen look nod',{mode:'illustration',diagram:{kind:'map',labels:['표징을 살핌','가까워짐을 깨달음','문 앞에 이르심']}});
v(30,'이 세대에 이루어질 말씀','예수께서 자신이 말씀하신 일이 이 세대 안에 이루어질 것이라고 엄숙히 선언하세요.',['예수','제자들'],'look speak count listen bow stand');
v(31,'사라지지 않을 말씀','하늘과 땅이 지나가도 예수의 말씀은 사라지지 않는다는 선언을, 배경은 희미해져도 남는 글빛으로 상징해요.',['예수','제자들'],'look speak point hold listen stand',{mode:'illustration',diagram:{kind:'promise',labels:['지나가는 하늘과 땅','남아 있는 말씀','변하지 않는 약속']}});
v(32,'그날과 그때를 아는 이는 아버지','천사도 아들도 그날과 때를 알지 못하고 아버지만 아신다고 말씀하세요. 하나님을 무대 위 인물로 묘사하지 않아요.',['예수','천사들','제자들','하나님'],'look speak lower listen wait stand',{mode:'illustration',diagram:{kind:'warning',labels:['정해진 때','사람이 알 수 없음','아버지만 아심']}});
v(33,'주의하고 깨어 있으라','때를 알 수 없으므로 제자들이 졸음을 떨치고 깨어 살피도록 예수께서 당부하세요.',['예수','제자들'],'look speak rise inspect listen stand');
v(34,'각 종에게 일을 맡기고 떠난 주인','여행을 떠나는 집주인이 종들에게 각자 맡을 일을 나누고 문지기에게 깨어 있으라 일러요.',['집주인','종들','문지기'],'gather speak point receive turn walk',{setting:'house'});
v(35,'저녁부터 새벽까지 깨어 기다림','집주인이 저녁, 한밤, 닭 울 때, 새벽 중 언제 돌아올지 모르므로 문지기와 종들이 깨어 기다려요.',['집주인','종들','문지기'],'look inspect wait listen turn wait',{setting:'house',night:true});
v(36,'갑작스러운 귀가에 잠들지 않도록','주인이 갑자기 돌아와 종들이 잠든 모습을 보지 않도록 깨어 있으라는 경계를 이어가요.',['집주인','종들','문지기'],'walk inspect startle rise look wait',{setting:'house',night:true});
v(37,'모든 사람에게 주신 깨어 있음의 말씀','예수께서 제자들에게 하신 깨어 있으라는 당부가 모든 사람에게 향함을 넓은 무리를 향한 손짓으로 마무리해요.',['예수','제자들','무리'],'look speak extend gather listen stand');

