additionalPeople[14]=people(['제자들','열두 제자','대제사장들','서기관들','장로들','무리','베다니의 시몬','향유를 부은 여자','가난한 사람들','물동이를 든 사람','집주인','두 제자','경비병','대제사장의 종','곁에 선 사람','종','공회','거짓 증인들','여종','사람들']);
v(1,'명절을 앞두고 모의하는 지도자들','유월절과 무교절을 앞두고 대제사장들과 서기관들이 예수를 몰래 붙잡아 죽일 방도를 의논해요.',['대제사장들','서기관들'],'gather speak point look confer wait',{setting:'chamber',emotion:'tense'});
v(2,'명절 소동을 염려함','지도자들은 명절 중에 일을 벌이면 무리가 소동할 수 있다고 걱정하며 시기를 저울질해요.',['대제사장들','서기관들'],'look speak listen lower confer wait',{setting:'chamber',emotion:'worried'});
v(3,'시몬의 집에서 향유를 부은 여자','베다니 시몬의 식탁에서 한 여자가 값진 향유 병을 열어 예수의 머리에 부어요.',['예수','향유를 부은 여자','베다니의 시몬'],'sit approach break pour lower look',{setting:'chamber',prop:'perfume',effect:'anoint-head'});
v(4,'향유를 낭비라며 화내는 사람들','곁에 있던 이들이 향유를 왜 낭비하느냐며 서로 불평해요. 여인을 몰아세우는 표정과 시선을 보여요.',['사람들','향유를 부은 여자','예수'],'look turn speak point lower wait',{setting:'chamber',emotion:'angry'});
v(5,'삼백 데나리온을 셈하는 비난','사람들은 향유를 팔아 가난한 사람을 도울 수 있었다며 여인을 꾸짖어요. 향유 값은 숫자 표식으로만 제시해요.',['사람들','향유를 부은 여자','예수','가난한 사람들'],'count speak point lower listen wait',{setting:'chamber',prop:'coin'});
v(6,'여인을 괴롭히지 말라 하심','예수께서 여인을 괴롭히지 말라고 막아서고, 그가 자신에게 좋은 일을 했다고 말씀하세요.',['예수','향유를 부은 여자','사람들'],'turn signal speak reach listen lower',{setting:'chamber'});
v(7,'가난한 이들을 도울 기회와 때','예수께서 가난한 이들을 언제든 도울 수 있지만 자신은 늘 함께 있지 않다고 설명하세요.',['예수','향유를 부은 여자','가난한 사람들'],'speak extend point listen look stand');
v(8,'장례를 미리 준비한 향유','여자가 할 수 있는 일을 해 예수의 장례를 미리 준비했다는 뜻을 조용한 향기와 낮아진 시선으로 나타내요.',['예수','향유를 부은 여자'],'look pour lower listen wait stand',{mode:'illustration',diagram:{kind:'promise',labels:['여인이 할 수 있는 일','장례를 앞선 준비','기억될 헌신']},prop:'perfume',effect:'anoint-head'});
v(9,'복음과 함께 기억될 행위','복음이 전해지는 곳마다 여인이 한 일이 기억될 것이라는 예수의 말씀을, 퍼져나가는 작은 빛으로 표현해요.',['예수','향유를 부은 여자','제자들'],'speak point gather listen remember stand',{mode:'illustration',diagram:{kind:'map',labels:['복음이 전해지는 곳','여인의 행위','기억에 남음']}});
v(10,'유다가 지도자들에게 찾아감','열두 제자 중 가룟 유다가 예수를 넘겨주려고 대제사장들에게 찾아가요.',['가룟 유다','대제사장들'],'turn walk approach speak listen wait',{setting:'chamber',emotion:'tense'});
v(11,'돈을 약속하고 기회를 찾음','지도자들은 유다의 제안을 반기며 돈을 약속하고, 유다는 넘겨줄 기회를 살펴요.',['가룟 유다','대제사장들'],'listen receive count look turn wait',{setting:'chamber',prop:'coin'});
v(12,'유월절 식사 장소를 묻는 제자들','유월절 양을 잡는 날에 제자들이 예수께 식사 준비 장소를 여쭈어요.',['예수','제자들'],'gather speak point listen wait stand',{setting:'chamber'});
v(13,'물동이 든 이를 따라가라 하심','예수께서 제자 둘을 성으로 보내시며 물동이를 든 사람을 만나면 따라가라고 하세요.',['예수','두 제자','물동이를 든 사람'],'speak signal turn walk follow wait',{setting:'road',prop:'water'});
v(14,'집주인에게 객실을 물으라 하심','예수께서 물동이를 든 이가 들어가는 집의 주인에게 객실을 물으라고 일러 주세요.',['두 제자','물동이를 든 사람','집주인'],'follow halt speak listen point wait',{setting:'house'});
v(15,'준비된 큰 다락방','집주인이 자리가 마련된 큰 다락방을 보여주고 제자들이 그곳에서 식사를 준비해요.',['집주인','두 제자'],'open point inspect place gather stand',{setting:'chamber',prop:'table'});
v(16,'말씀대로 마련된 유월절 식사','제자들이 성으로 가서 예수께서 말씀하신 사람과 집을 만나 유월절 음식을 준비해요.',['두 제자','집주인'],'walk inspect speak receive place prepare',{setting:'chamber',prop:'table'});
v(17,'저물어 열두 제자와 오심','저녁이 되자 예수께서 열두 제자와 함께 마련된 식사 자리로 오세요.',['예수','열두 제자'],'walk gather sit look wait stand',{setting:'chamber',prop:'table'});
v(18,'함께 먹는 이가 배반하리라','식탁에 둘러앉아 먹는 중 예수께서 함께 먹는 사람 가운데 자신을 넘길 이가 있다고 알리세요.',['예수','열두 제자','가룟 유다'],'sit eat halt speak look lower',{setting:'chamber',prop:'table',emotion:'solemn'});
v(19,'근심하며 자신인지 묻는 제자들','제자들이 근심하며 차례로 자신이 배반자인지 묻고 서로의 얼굴을 살펴요.',['열두 제자','예수'],'look lower speak turn listen wait',{setting:'chamber',emotion:'sad'});
v(20,'같은 그릇에 손을 넣는 이','예수께서 열둘 중 함께 그릇에 손을 넣는 이라고 답하세요. 식탁 위 손의 움직임으로 가까운 단서를 보여요.',['예수','열두 제자','가룟 유다'],'speak point reach inspect lower wait',{setting:'chamber',prop:'bowl'});
v(21,'기록된 길과 배반자의 책임','예수께서 인자의 길은 기록된 대로 가지만 넘기는 사람에게 화가 있다고 엄중히 말씀하세요.',['예수','열두 제자','가룟 유다'],'look speak lower listen retreat wait',{setting:'chamber',emotion:'solemn'});
v(22,'떡을 떼어 제자들에게 주심','식사 중 예수께서 떡을 축복하고 떼어 제자들에게 건네며 이를 자신의 몸을 가리키는 표지로 설명하세요.',['예수','열두 제자'],'lift bless break extend receive look',{setting:'chamber',prop:'bread',effect:'bread-share'});
v(23,'잔을 들어 감사하고 나누심','예수께서 잔을 들어 감사하고 제자들에게 건네시며 모두가 받아 마셔요.',['예수','열두 제자'],'lift pray extend receive drink lower',{setting:'chamber',prop:'cup',effect:'bread-share'});
v(24,'많은 이를 위한 언약의 잔','예수께서 잔을 많은 이를 위한 언약의 피를 가리키는 표지로 설명하세요. 피를 시각적으로 재현하지 않고 잔과 빛으로 상징해요.',['예수','열두 제자'],'hold speak point listen lower stand',{setting:'chamber',prop:'cup',effect:'bread-share'});
v(25,'하나님 나라의 새 잔을 기다림','하나님 나라에서 새것을 마실 날까지 포도나무에서 난 것을 마시지 않으리라는 말씀을 전하세요.',['예수','열두 제자'],'hold speak look listen wait stand',{mode:'illustration',diagram:{kind:'promise',labels:['지금의 식탁','하나님 나라','새것을 마실 날']},prop:'cup'});
v(26,'찬송 후 감람산으로 향함','예수와 제자들이 찬송한 뒤 감람산으로 걸어가요.',['예수','열두 제자'],'rise sing turn walk walk walk',{setting:'mountain'});
v(27,'흩어질 양 떼를 말씀하심','예수께서 제자들이 자신을 버리고 흩어질 것이라고 예고하며 목자와 양의 표상을 말씀하세요.',['예수','열두 제자'],'look speak lower retreat listen turn',{mode:'illustration',diagram:{kind:'herd',labels:['목자를 치심','흩어지는 양들','제자들의 두려움']}});
v(28,'부활 뒤 갈릴리에서 만나리라','예수께서 살아난 뒤 제자들보다 먼저 갈릴리로 가겠다고 약속하세요.',['예수','열두 제자'],'speak point listen look walk stand',{mode:'illustration',diagram:{kind:'map',labels:['죽음 뒤','다시 살아남','갈릴리에서 만남']}});
v(29,'베드로의 굳은 맹세','베드로가 다른 제자들이 떠나도 자신은 그렇지 않겠다고 단호하게 말해요.',['베드로','예수','열두 제자'],'step speak point listen lower stand',{setting:'mountain'});
v(30,'세 번 부인을 미리 알리심','예수께서 닭이 두 번 울기 전에 베드로가 세 번 부인할 것이라고 알려 주세요.',['예수','베드로'],'look speak count listen recoil wait',{setting:'mountain',effect:'rooster-call'});
v(31,'죽어도 부인하지 않겠다 답함','베드로가 죽더라도 부인하지 않겠다고 힘주어 말하고 다른 제자들도 같은 뜻을 밝혀요.',['베드로','열두 제자','예수'],'speak pledge gather listen nod stand',{setting:'mountain'});
v(32,'겟세마네에 이르러 기도하심','예수와 제자들이 겟세마네에 도착하고 예수께서 기도하는 동안 앉아 있으라고 하세요.',['예수','열두 제자'],'walk halt point sit turn kneel',{setting:'garden'});
v(33,'세 제자와 더 나아가심','예수께서 베드로와 야고보와 요한을 데리고 가며 깊은 근심을 드러내세요.',['예수','베드로','야고보','요한'],'walk lower look follow halt wait',{setting:'garden',emotion:'sad'});
v(34,'깨어 있으라고 부탁하심','예수께서 마음의 괴로움을 나누고 세 제자에게 곁에 머물며 깨어 있으라고 부탁하세요.',['예수','베드로','야고보','요한'],'speak lower reach listen sit wait',{setting:'garden',emotion:'sad'});
v(35,'땅에 엎드려 기도하심','예수께서 조금 더 나아가 땅에 엎드려 그 시간이 지나가기를 기도하세요.',['예수'],'walk kneel prostrate pray wait',{setting:'garden',emotion:'sad'});
v(36,'아버지의 뜻을 구하는 기도','예수께서 아버지께 모든 것이 가능함을 고백하면서도 자신의 뜻보다 아버지의 뜻을 구하세요. 하나님을 별도 인물로 무대에 세우지 않고 예수의 기도 동작으로 표현해요.',['예수'],'prostrate pray speak lower wait rise',{setting:'garden',emotion:'solemn'});
v(37,'잠든 제자들을 깨우심','예수께서 돌아와 잠든 제자들을 보시고 베드로에게 깨어 있을 수 없었느냐고 물으세요.',['예수','베드로','야고보','요한'],'walk inspect sleep speak startle',{setting:'garden'});
v(38,'시험에 들지 않게 기도하라','예수께서 깨어 기도하라고 하시며 마음의 바람과 몸의 약함을 함께 일러 주세요.',['예수','베드로','야고보','요한'],'speak point kneel pray listen rise',{setting:'garden'});
v(39,'같은 말씀으로 다시 기도하심','예수께서 다시 떨어져 나가 같은 뜻으로 기도하세요. 반복 기도는 같은 자세의 고정 복제가 아니라 숨을 고르고 엎드리는 흐름으로 표현해요.',['예수'],'turn walk kneel prostrate pray',{setting:'garden'});
v(40,'피곤해 다시 잠든 제자들','예수께서 돌아오시자 제자들은 눈이 무거워 다시 잠들어 대답하지 못해요.',['예수','베드로','야고보','요한'],'sleep walk inspect lower wait stand',{setting:'garden'});
v(41,'세 번째로 오셔서 때를 알리심','세 번째 돌아오신 예수께서 이제 쉬고 일어날 때이며 자신을 넘길 자가 가까이 왔다고 알리세요.',['예수','열두 제자'],'walk speak signal rise listen stand',{setting:'garden',emotion:'solemn'});
v(42,'일어나 함께 가자 하심','예수께서 제자들에게 함께 일어나 가자고 하시며 넘기는 이가 가까이 왔다고 말씀하세요.',['예수','열두 제자'],'rise point walk look gather stand',{setting:'garden'});
v(43,'유다와 무리가 도착함','예수께서 말씀하실 때 유다가 대제사장들과 서기관들과 장로들이 보낸 무리를 이끌고 와요. 무기는 위협의 배경으로만 둬요.',['가룟 유다','대제사장들','서기관들','장로들','무리','예수'],'walk gather halt point look surround',{setting:'garden',prop:'sword'});
v(44,'입맞춤을 체포 신호로 삼음','유다가 미리 정한 신호로 입맞추는 사람을 붙잡으라고 무리에게 알렸어요.',['가룟 유다','무리','예수'],'speak point approach listen wait',{setting:'garden'});
v(45,'선생님이라 부르며 입맞춤함','유다가 예수께 다가와 선생님이라 부르며 입맞추고, 무리는 그 신호를 알아봐요.',['가룟 유다','예수','무리'],'approach speak reach touch turn wait',{setting:'garden'});
v(46,'예수를 붙잡음','무리가 예수께 손을 대어 체포해요. 몸싸움이나 폭행은 과장하지 않고 붙들린 순간을 짧게 표현해요.',['무리','예수','열두 제자'],'reach hold recoil turn gather wait',{setting:'garden',effect:'capture'});
v(47,'칼에 맞은 종의 귀','곁에 있던 사람이 칼을 휘둘러 대제사장의 종의 귀를 다치게 해요. 상처나 피는 그리지 않고 예수의 제지와 놀란 표정에 초점을 둬요.',['곁에 선 사람','대제사장의 종','예수','무리'],'look windup strike recoil reach listen',{setting:'garden',prop:'sword'});
v(48,'강도 잡듯 나온 무리를 책망함','예수께서 자신을 강도처럼 잡으러 칼과 몽둥이를 들고 나왔느냐고 무리에게 물으세요.',['예수','무리'],'look speak point hold listen lower',{setting:'garden',emotion:'stern'});
v(49,'성전에서 가르칠 때는 잡지 않음','예수께서 성전에서 날마다 가르칠 때에는 붙잡지 않았음을 지적하고, 지금 일은 성경을 이루는 과정이라고 말씀하세요.',['예수','무리'],'speak point listen lower wait stand',{setting:'garden'});
v(50,'흩어져 도망가는 제자들','제자들이 예수를 두고 모두 달아나요. 한 방향으로 몰리지 않도록 서로 다른 길로 흩어지는 실루엣을 보여요.',['열두 제자','예수','무리'],'startle turn run run retreat disappear',{setting:'garden'});
v(51,'홑이불만 걸친 청년이 붙잡힘','한 청년이 홑이불을 걸치고 예수를 따라오다 무리에게 붙들리는 장면이에요.',['벗은 청년','무리','예수'],'follow reach hold recoil turn wait',{setting:'garden'});
v(52,'홑이불을 두고 달아남','청년이 홑이불을 놓고 달아나요. 노출이나 신체를 그리지 않고 천과 멀어지는 뒷모습만 표현해요.',['벗은 청년','무리'],'release turn run run retreat disappear',{setting:'garden',prop:'linen'});
v(53,'대제사장에게 끌려가 모인 공회','무리가 예수를 대제사장에게 데려가자 대제사장들과 장로들과 서기관들이 모여요.',['예수','대제사장','대제사장들','장로들','서기관들'],'walk gather halt look speak wait',{setting:'court'});
v(54,'멀찍이 따라가 불을 쬐는 베드로','베드로가 거리를 두고 대제사장의 집 뜰까지 따라가 경비병들과 불을 쬐며 상황을 살펴요.',['베드로','경비병'],'walk hide sit warm look wait',{setting:'courtyard',prop:'fire'});
v(55,'정죄할 증거를 찾는 공회','대제사장들과 공회가 예수를 죽일 증거를 찾지만 뜻대로 얻지 못해요.',['대제사장','대제사장들','공회','예수'],'gather inspect speak look wait lower',{setting:'court'});
v(56,'서로 맞지 않는 거짓 증언','많은 거짓 증인이 나서지만 말이 서로 맞지 않아 증언이 흔들려요.',['거짓 증인들','대제사장들','예수'],'speak point turn inspect lower wait',{setting:'court'});
v(57,'거짓 증언을 시작하는 사람들','몇 사람이 일어나 예수를 고발하는 말을 시작해요. 실제 사실과 다른 증언임을 분명히 하고 고발 장면만 간결히 나타내요.',['거짓 증인들','예수','대제사장들'],'rise speak point listen wait stand',{setting:'court'});
v(58,'성전 발언을 왜곡해 고발함','증인들이 성전을 헐고 사흘 만에 다시 세우겠다는 말을 들었다고 주장해요. 예수의 실제 가르침으로 확정하지 않고 증언자의 발언으로 표시해요.',['거짓 증인들','예수','대제사장들'],'speak point listen inspect lower wait',{setting:'court'});
v(59,'일치하지 않는 증언','그 증언마저 서로 맞지 않아 공회가 확정된 근거를 찾지 못해요.',['거짓 증인들','대제사장들','공회'],'turn confer inspect lower wait stand',{setting:'court'});
v(60,'대제사장이 직접 심문함','대제사장이 일어나 예수께 증언에 답하라고 묻지만 예수께서는 침묵하세요.',['대제사장','예수','공회'],'rise point speak listen lower wait',{setting:'court'});
v(61,'그리스도인지 다시 묻는 대제사장','대제사장이 찬송받을 이의 아들 그리스도인지 묻고 예수께서는 침묵을 지키세요.',['대제사장','예수','공회'],'look speak wait lower listen stand',{setting:'court'});
v(62,'자신의 정체와 올 일을 밝히심','예수께서 자신이 그리스도임을 밝히고 인자가 권능자의 우편에 앉으며 구름 가운데 오는 것을 말하세요.',['예수','대제사장','공회'],'rise speak point listen recoil stand',{setting:'court'});
v(63,'옷을 찢는 대제사장','대제사장이 옷을 찢으며 더는 증언이 필요 없다고 선언해요.',['대제사장','공회','예수'],'tear speak point gather look wait',{setting:'court',emotion:'angry'});
v(64,'사형에 해당한다고 정죄함','공회가 그 말씀을 신성모독으로 판단하고 사형에 해당한다고 정죄해요.',['대제사장','공회','예수'],'speak point gather lower listen wait',{setting:'court',emotion:'tense'});
v(65,'모욕과 폭행을 당하심','사람들이 예수를 모욕하고 가리며 때려요. 폭력의 접촉은 화면 밖으로 두고 가려진 얼굴과 둘러싼 그림자로만 다뤄요.',['예수','사람들','경비병'],'surround cover recoil lower turn wait',{setting:'court',emotion:'sad'});
v(66,'뜰에서 베드로에게 다가온 여종','아랫뜰에서 불을 쬐던 베드로에게 대제사장의 여종이 다가와요.',['베드로','여종'],'sit approach look point listen wait',{setting:'courtyard',prop:'fire'});
v(67,'예수와 함께 있던 사람이라 알아봄','여종이 베드로를 살펴보고 예수와 함께 있었다고 말해요.',['여종','베드로','사람들'],'look point speak recoil lower listen',{setting:'courtyard'});
v(68,'첫 부인과 닭 울음','베드로가 무슨 말인지 모른다고 부인하며 앞뜰로 옮기고 닭이 한 번 울어요.',['베드로','여종','사람들'],'turn speak retreat walk listen startle',{setting:'courtyard',effect:'rooster-call'});
v(69,'다시 베드로를 알아본 여종','여종이 곁의 사람들에게 베드로도 예수의 무리라고 다시 말해요.',['여종','베드로','사람들'],'look point speak turn listen wait',{setting:'courtyard'});
v(70,'갈릴리 말씨로 다시 의심받음','잠시 뒤 사람들도 베드로가 갈릴리 사람이라며 같은 무리라고 말하고 베드로는 다시 부인해요.',['베드로','사람들'],'speak point recoil turn deny listen',{setting:'courtyard',effect:'rooster-call'});
v(71,'모른다고 맹세하며 부인함','베드로가 맹세하고 자신은 그 사람을 모른다고 강하게 부인해요.',['베드로','사람들'],'speak pledge lower retreat listen wait',{setting:'courtyard',emotion:'tense'});
v(72,'두 번째 닭 울음과 베드로의 눈물','닭이 두 번째 울자 베드로는 예수의 예고를 기억하고 무너져 울어요. 닭 울음 뒤 표정과 몸이 천천히 낮아지는 흐름으로 마무리해요.',['베드로','예수'],'listen startle remember lower kneel mourn',{setting:'courtyard',effect:'rooster-call',emotion:'sad'});
